function setupVisibleMusicAutoplay(){if(!('IntersectionObserver' in window))return;window._texxMusicObserver?.disconnect?.();window._texxMusicObserver=new IntersectionObserver(entries=>{if(!state.musicAutoplayUnlocked)return;const best=entries.filter(e=>e.isIntersecting&&e.intersectionRatio>=.65).sort((a,b)=>b.intersectionRatio-a.intersectionRatio)[0];if(!best)return;const c=best.target.querySelector('.post-music-player');if(c&&String(c.dataset.musicPost)!==String(state.activeMusicPostId))playPostMusic(c,false)},{threshold:[.65,.85]});document.querySelectorAll('.post,.reel-card').forEach(el=>window._texxMusicObserver.observe(el))}

function searchMusicCatalog(){const q=$('musicSearch').value.trim();if(!q){$('musicSearch').focus();return toast('Enter an artist or song to search.')}const btn=$('musicSearchBtn');btn.disabled=true;btn.textContent='Searching…';$('musicSearchStatus').textContent='Searching the music catalog…';$('musicResults').innerHTML='';const cb=`texxMusic_${Date.now()}_${Math.random().toString(36).slice(2)}`;let script=document.createElement('script');let finished=false;const cleanup=()=>{if(finished)return;finished=true;btn.disabled=false;btn.textContent='Search';try{delete window[cb]}catch{}script.remove()};window[cb]=(payload)=>{const results=(payload?.results||[]).filter(x=>x.kind==='song'||x.wrapperType==='track').slice(0,15);renderMusicResults(results);$('musicSearchStatus').textContent=results.length?`${results.length} tracks found. Tap one to select it.`:'No tracks found. Try a different search.';cleanup()};script.onerror=()=>{$('musicSearchStatus').textContent='Music search is temporarily unavailable. You can still add a streaming link manually.';cleanup()};script.src=`https://itunes.apple.com/search?term=${encodeURIComponent(q)}&entity=song&limit=15&country=US&callback=${encodeURIComponent(cb)}`;document.head.appendChild(script);setTimeout(()=>{if(!finished){$('musicSearchStatus').textContent='Music search timed out. Try again or add a link manually.';cleanup()}},10000)}
