async function syncLegacyVideoCovers(){const map=getStoredVideoCovers();const entries=Object.entries(map);if(!entries.length||!state.user)return;for(const [postId,url] of entries){if(!url)continue;const {data,error}=await sb.from('posts').update({cover_url:url}).eq('id',postId).eq('user_id',state.user.id).is('cover_url',null).select('id').maybeSingle();if(!error&&data?.id)setStoredVideoCover(postId,null)}}
