async function toggleLike(postId,isLiked,fromReels=false){
  if(isLiked){const {error}=await sb.from('likes').delete().eq('post_id',postId).eq('user_id',state.user.id);if(error)return toast(error.message)}
  else {const {error}=await sb.from('likes').insert({post_id:postId,user_id:state.user.id});if(error)return toast(error.message)}
  await loadFeed();if(fromReels||state.currentView==='reels')await loadReels();
}

async function openComments(postId){state.commentPostId=postId;$('commentsModal').classList.remove('hidden');await loadComments()}
async function reportPost(postId,ownerId){
  if(ownerId===state.user.id){toast('This is your own post.');return}
  const choice=prompt(`Report this post? Enter a number:
1 Sexual or nude content
2 Graphic violence
3 Hate or harassment
4 Drugs or gambling promotion
5 Bullying, doxxing, or private information
6 Other`);
  const reasons={1:'sexual_content',2:'graphic_violence',3:'hate_harassment',4:'drugs_gambling',5:'bullying_doxxing',6:'other'};
  const reason=reasons[Number(choice)];if(!reason)return;
  const details=reason==='other'?prompt('Briefly describe the concern (optional):')||null:null;
  const {error}=await sb.from('reports').insert({reporter_id:state.user.id,post_id:postId,reason,details});
  if(error){toast(error.code==='23505'?'You already reported this post.':error.message);return}
  toast('Report submitted. Thank you for helping keep TEXX SOCIAL safe.');
}

