async function getOrCreateThread(otherUserId){
  if(!otherUserId||otherUserId===state.user.id)return null;
  const a=state.user.id<otherUserId?state.user.id:otherUserId;const b=state.user.id<otherUserId?otherUserId:state.user.id;
  let {data,error}=await sb.from('direct_threads').select('id,user_a,user_b').eq('user_a',a).eq('user_b',b).maybeSingle();
  if(error)return toast(error.message),null;
  if(!data){const res=await sb.from('direct_threads').insert({user_a:a,user_b:b}).select('id,user_a,user_b').single();if(res.error){if(res.error.code==='23505'){const retry=await sb.from('direct_threads').select('id,user_a,user_b').eq('user_a',a).eq('user_b',b).single();if(retry.error)return toast(retry.error.message),null;data=retry.data}else return toast(res.error.message),null}else data=res.data}
  return data;
}
async function loadThreads(){
  if(!state.user)return;const list=$('threadList');if(!list)return;list.innerHTML='<div class="empty"><p>Loading messages…</p></div>';
  const {data:threads,error}=await sb.from('direct_threads').select('id,user_a,user_b,created_at').or(`user_a.eq.${state.user.id},user_b.eq.${state.user.id}`).order('created_at',{ascending:false});
  if(error){list.innerHTML='';return toast(error.message)}if(!threads?.length){list.innerHTML='<div class="empty"><p>No messages yet.</p><button class="primary" id="startFirstMessage">Start a message</button></div>';const b=$('startFirstMessage');if(b)b.onclick=showNewMessagePicker;return}
  const otherIds=[...new Set(threads.map(t=>t.user_a===state.user.id?t.user_b:t.user_a))];
  const [{data:people},{data:msgs}]=await Promise.all([sb.from('profiles').select('id,username,display_name,avatar_url').in('id',otherIds),sb.from('direct_messages').select('id,thread_id,sender_id,body,media_url,media_type,created_at').in('thread_id',threads.map(t=>t.id)).order('created_at',{ascending:false})]);
  const profiles=new Map((people||[]).map(p=>[p.id,p]));const latest=new Map();(msgs||[]).forEach(m=>{if(!latest.has(m.thread_id))latest.set(m.thread_id,m)});
  list.innerHTML=threads.map(t=>{const otherId=t.user_a===state.user.id?t.user_b:t.user_a;const p=profiles.get(otherId)||{};const m=latest.get(t.id);return `<button class="thread-row ${state.messageThreadId===t.id?'active':''}" data-thread="${t.id}" data-user="${otherId}"><div class="avatar">${p.avatar_url?`<img src="${safe(p.avatar_url)}" alt=""/>`:initials(p.username||'TS')}</div><div class="copy"><strong>@${safe(p.username||'user')}</strong><span>${safe(m?.body||(m?.media_url?(m?.media_type==='video'?'Shared a video':'Shared a photo'):'Start a conversation'))}</span></div></button>`}).join('');
  list.querySelectorAll('.thread-row').forEach(b=>b.onclick=()=>openThread(b.dataset.thread,b.dataset.user));
}
async function showNewMessagePicker(){
  const list=$('threadList');list.innerHTML='<div class="new-message-panel"><input id="newMessageSearch" class="new-message-search" type="search" placeholder="Search @username"/><div id="newMessagePeople"></div></div>';
  const load=async()=>{const q=$('newMessageSearch').value.trim().replace(/^@/,'');let req=sb.from('profiles').select('id,username,display_name,avatar_url').neq('id',state.user.id).order('username').limit(30);if(q)req=req.ilike('username',`%${q}%`);const {data,error}=await req;if(error)return toast(error.message);$('newMessagePeople').innerHTML=(data||[]).map(p=>`<button class="people-row start-dm" data-user="${p.id}" style="width:100%;border:0;background:transparent;text-align:left"><div class="avatar">${p.avatar_url?`<img src="${safe(p.avatar_url)}" alt=""/>`:initials(p.username)}</div><div class="copy"><strong>@${safe(p.username)}</strong><span>${safe(p.display_name||'')}</span></div></button>`).join('')||'<div class="empty"><p>No people found.</p></div>';$('newMessagePeople').querySelectorAll('.start-dm').forEach(b=>b.onclick=async()=>{const t=await getOrCreateThread(b.dataset.user);if(t)await openThread(t.id,b.dataset.user)})};
  $('newMessageSearch').addEventListener('input',()=>{clearTimeout(state.searchT);state.searchT=setTimeout(load,220)});await load();
}
async function openThread(threadId,otherUserId){
  state.messageThreadId=threadId;state.messageOtherUser=otherUserId;$('messagesShell').classList.add('chat-open');
  const [{data:p,error:pErr},{data:messages,error:mErr}]=await Promise.all([sb.from('profiles').select('id,username,display_name,avatar_url').eq('id',otherUserId).single(),sb.from('direct_messages').select('id,sender_id,body,media_url,storage_path,media_type,created_at').eq('thread_id',threadId).order('created_at',{ascending:true}).limit(300)]);
  if(pErr||mErr)return toast((pErr||mErr).message);
  $('chatPane').innerHTML=`<div class="chat-head"><button class="chat-back" id="chatBack" aria-label="Back to messages">‹</button><div class="avatar">${p.avatar_url?`<img src="${safe(p.avatar_url)}" alt=""/>`:initials(p.username)}</div><div class="copy"><strong>@${safe(p.username)}</strong><span>${safe(p.display_name||'')}</span></div></div><div id="chatMessages" class="chat-messages">${(messages||[]).map(m=>`<div class="bubble ${m.sender_id===state.user.id?'mine':''}">${m.media_url?`<a class="bubble-media" href="${safe(m.media_url)}" target="_blank" rel="noopener noreferrer">${m.media_type==='video'?`<video src="${safe(m.media_url)}" controls playsinline preload="metadata"></video>`:`<img src="${safe(m.media_url)}" alt="Shared content"/>`}</a>`:''}${m.body?safe(m.body):''}<time>${timeAgo(m.created_at)}</time></div>`).join('')||'<div class="chat-empty">No messages yet. Say hello.</div>'}</div><form id="chatForm" class="chat-form"><input id="chatInput" maxlength="2000" autocomplete="off" placeholder="Message @${safe(p.username)}" required/><button type="submit">Send</button></form>`;
  $('chatBack').onclick=()=>{$('messagesShell').classList.remove('chat-open');state.messageThreadId=null;state.messageOtherUser=null;loadThreads()};
  $('chatForm').addEventListener('submit',async e=>{e.preventDefault();const input=$('chatInput');const body=input.value.trim();if(!body)return;const btn=e.currentTarget.querySelector('button');btn.disabled=true;const {error}=await sb.from('direct_messages').insert({thread_id:threadId,sender_id:state.user.id,body});btn.disabled=false;if(error)return toast(error.message);input.value='';await refreshOpenThread(false);await loadThreads()});
  const box=$('chatMessages');box.scrollTop=box.scrollHeight;await loadThreads();startMessagePolling();
}
async function refreshOpenThread(scroll=true){
  if(!state.messageThreadId||state.currentView!=='messages')return;const {data,error}=await sb.from('direct_messages').select('id,sender_id,body,media_url,storage_path,media_type,created_at').eq('thread_id',state.messageThreadId).order('created_at',{ascending:true}).limit(300);if(error)return;const box=$('chatMessages');if(!box)return;const nearBottom=box.scrollHeight-box.scrollTop-box.clientHeight<80;box.innerHTML=(data||[]).map(m=>`<div class="bubble ${m.sender_id===state.user.id?'mine':''}">${m.media_url?`<a class="bubble-media" href="${safe(m.media_url)}" target="_blank" rel="noopener noreferrer">${m.media_type==='video'?`<video src="${safe(m.media_url)}" controls playsinline preload="metadata"></video>`:`<img src="${safe(m.media_url)}" alt="Shared content"/>`}</a>`:''}${m.body?safe(m.body):''}<time>${timeAgo(m.created_at)}</time></div>`).join('')||'<div class="chat-empty">No messages yet. Say hello.</div>';if(scroll||nearBottom)box.scrollTop=box.scrollHeight;
}
function startMessagePolling(){clearInterval(state.messageTimer);state.messageTimer=setInterval(()=>{if(state.currentView==='messages'){refreshOpenThread(false);loadThreads()}else clearInterval(state.messageTimer)},3000)}
async function openMessageWithUser(userId){const t=await getOrCreateThread(userId);if(!t)return;showView('messages');await openThread(t.id,userId)}

async function loadPeople(query=''){let q=sb.from('profiles').select('id,username,display_name,avatar_url').neq('id',state.user.id).order('username').limit(40);if(query)q=q.ilike('username',`%${query.replace(/^@/,'')}%`);const {data,error}=await q;if(error)return toast(error.message);const {data:follows}=await sb.from('follows').select('following_id').eq('follower_id',state.user.id);const set=new Set((follows||[]).map(x=>x.following_id));$('peopleList').innerHTML=(data||[]).map(p=>`<div class="people-row"><button class="person user-open" data-user="${p.id}" style="border:0;background:transparent;padding:0;text-align:left;flex:1"><div class="avatar">${p.avatar_url?`<img src="${safe(p.avatar_url)}" alt=""/>`:initials(p.username)}</div><div class="copy"><strong>@${safe(p.username)}</strong><span>${safe(p.display_name||'')}</span></div></button><button class="follow-btn ${set.has(p.id)?'following':''}" data-follow="${p.id}" data-is="${set.has(p.id)}">${set.has(p.id)?'Following':'Follow'}</button></div>`).join('')||'<div class="empty"><p>No people found.</p></div>';$('peopleList').querySelectorAll('.follow-btn').forEach(b=>b.onclick=()=>toggleFollow(b.dataset.follow,b.dataset.is==='true'));$('peopleList').querySelectorAll('.user-open').forEach(b=>b.onclick=()=>showProfile(b.dataset.user))}
async function toggleFollow(userId,isFollowing){if(isFollowing){const {error}=await sb.from('follows').delete().eq('follower_id',state.user.id).eq('following_id',userId);if(error)return toast(error.message)}else{const {error}=await sb.from('follows').insert({follower_id:state.user.id,following_id:userId});if(error)return toast(error.message)}await loadPeople($('peopleSearch').value.trim())}
$('peopleSearch').addEventListener('input',()=>{clearTimeout(state.searchT);state.searchT=setTimeout(()=>loadPeople($('peopleSearch').value.trim()),250)});

