async function showFollowing(userId){
  const {data,error}=await sb.from('follows').select('following_id,profiles!follows_following_id_fkey(id,username,display_name,avatar_url)').eq('follower_id',userId).limit(100);if(error)return toast(error.message);
  $('profilePanel').innerHTML=`<div class="profile-card"><div class="screen-head" style="padding-left:0"><button class="text-btn" id="backProfile">← Back</button><h1 style="margin-top:12px">Following</h1></div><div class="people-list">${(data||[]).map(x=>{const p=x.profiles||{};return `<button class="people-row user-open" data-user="${p.id}" style="width:100%;border:0;background:transparent;text-align:left"><div class="avatar">${p.avatar_url?`<img src="${safe(p.avatar_url)}" alt=""/>`:initials(p.username)}</div><div class="copy"><strong>@${safe(p.username||'user')}</strong><span>${safe(p.display_name||'')}</span></div></button>`}).join('')||'<div class="empty"><p>Not following anyone yet.</p></div>'}</div></div>`;
  $('backProfile').onclick=()=>showProfile(userId);$('profilePanel').querySelectorAll('.user-open').forEach(b=>b.onclick=()=>showProfile(b.dataset.user));
}
async function changeAvatar(){
  const input=document.createElement('input');input.type='file';input.accept='image/jpeg,image/png,image/webp';input.style.display='none';document.body.appendChild(input);
  input.onchange=async()=>{const file=input.files&&input.files[0];input.remove();if(!file)return;if(!['image/jpeg','image/png','image/webp'].includes(file.type))return toast('Choose a JPG, PNG, or WebP image.');if(file.size>10*1024*1024)return toast('Profile photos must be 10 MB or smaller.');
    const ext=file.type==='image/png'?'png':file.type==='image/webp'?'webp':'jpg';const path=`${state.user.id}/avatars/${Date.now()}-${crypto.randomUUID()}.${ext}`;toast('Uploading profile photo…');
    const {error:upErr}=await sb.storage.from('media').upload(path,file,{contentType:file.type,cacheControl:'3600',upsert:false});if(upErr)return toast(upErr.message);
    const {data:urlData}=sb.storage.from('media').getPublicUrl(path);const avatarUrl=urlData.publicUrl;const {error}=await sb.from('profiles').update({avatar_url:avatarUrl,updated_at:new Date().toISOString()}).eq('id',state.user.id);if(error){await sb.storage.from('media').remove([path]);return toast(error.message)}
    await loadProfile();toast('Profile photo updated.');await showProfile(state.user.id);
  };input.click();
}

async function blockUser(userId,username){if(!confirm(`Block @${username||'this user'}? They won't be able to follow you, message you, or see your posts, and you'll stop seeing theirs. You can't undo this from here yet — contact support to unblock.`))return;const {error}=await sb.from('blocks').insert({blocker_id:state.user.id,blocked_id:userId});if(error)return toast(error.message);toast(`@${username||'User'} blocked.`);await Promise.all([loadFeed(),loadProfileStrip()]);showView('discover')}
async function deactivateAccount(){if(!confirm('Deactivate your account? Your profile and posts will be hidden until you sign back in and reactivate.'))return;const {error}=await sb.rpc('deactivate_my_account');if(error)return toast(error.message);toast('Account deactivated. Signing you out…');setTimeout(()=>sb.auth.signOut(),1200)}
async function deleteAccountForever(){const typed=prompt('This permanently deletes your account, posts, messages, and media. This cannot be undone.\n\nType DELETE to confirm:');if(typed!=='DELETE')return;const {data:sessionData}=await sb.auth.getSession();const token=sessionData?.session?.access_token;if(!token)return toast('Your session expired. Please log in again and retry.');toast('Deleting your account…');const {data,error}=await sb.functions.invoke('delete-account',{headers:{Authorization:`Bearer ${token}`}});if(error||!data?.ok){toast(error?.message||'Could not delete your account. Please try again.');return}toast('Account deleted.');await sb.auth.signOut()}

async function editProfile(){const display=prompt('Display name',state.profile.display_name||'');if(display===null)return;const bio=prompt('Bio',state.profile.bio||'');if(bio===null)return;const website=prompt('Website or profile link',state.profile.website_url||'');if(website===null)return;let normalized=website.trim();if(normalized&&!/^https?:\/\//i.test(normalized))normalized='https://'+normalized;try{if(normalized){const u=new URL(normalized);if(!['http:','https:'].includes(u.protocol))throw new Error()}}catch{return toast('Please enter a valid website link.')}const {error}=await sb.from('profiles').update({display_name:display.trim()||null,bio:bio.trim()||null,website_url:normalized||null,updated_at:new Date().toISOString()}).eq('id',state.user.id);if(error)return toast(error.message);await loadProfile();await showProfile()}

function showView(view){state.currentView=view;if(view!=='profile')state.currentProfileUserId=null;if(view!=='messages'){clearInterval(state.messageTimer);state.messageTimer=null}['feed','reels','discover','messages','profile','notifications'].forEach(v=>$(v+'View').classList.toggle('hidden',v!==view));document.querySelectorAll('[data-view]').forEach(b=>b.classList.toggle('active',b.dataset.view===view));window.scrollTo({top:0,behavior:'smooth'});if(view==='reels')loadReels();if(view==='discover')loadPeople();if(view==='messages'){state.messageThreadId=null;state.messageOtherUser=null;$('messagesShell')?.classList.remove('chat-open');loadThreads()}if(view==='profile')showProfile(state.user.id);if(view==='notifications')loadNotifications()}

const notifTypeCopy={follow:'started following you',like:'liked your post',comment:'commented on your post',message:'sent you a message',mention:'mentioned you',report_resolved:'Your report was reviewed'};
async function updateNotifBadge(){if(!state.user)return;const {count,error}=await sb.from('notifications').select('id',{count:'exact',head:true}).eq('recipient_id',state.user.id).is('read_at',null);if(error)return;const n=count||0;[$('notifBadgeTop'),$('notifBadgeSide')].forEach(el=>{if(!el)return;el.textContent=n>99?'99+':String(n);el.classList.toggle('hidden',n===0)})}
async function loadNotifications(){const list=$('notificationsList'),empty=$('notificationsEmpty');list.innerHTML='<div class="empty"><p>Loading…</p></div>';const {data,error}=await sb.from('notifications').select('id,type,read_at,created_at,actor_id,post_id,profiles!notifications_actor_id_fkey(username,display_name,avatar_url)').eq('recipient_id',state.user.id).order('created_at',{ascending:false}).limit(50);if(error){list.innerHTML='';toast(error.message);return}empty.classList.toggle('hidden',(data||[]).length>0);list.innerHTML=(data||[]).map(n=>{const p=n.profiles||{};const label=notifTypeCopy[n.type]||'sent you a notification';return `<button class="notif-row ${n.read_at?'':'unread'}" data-notif="${n.id}" data-post="${n.post_id||''}"><div class="avatar">${p.avatar_url?`<img src="${safe(p.avatar_url)}" alt=""/>`:initials(p.username||'TS')}</div><div class="copy"><strong>@${safe(p.username||'someone')}</strong> ${safe(label)}<div class="time">${timeAgo(n.created_at)}</div></div></button>`}).join('');list.querySelectorAll('[data-notif]').forEach(b=>b.onclick=async()=>{await sb.from('notifications').update({read_at:new Date().toISOString()}).eq('id',b.dataset.notif);b.classList.remove('unread');await updateNotifBadge();const postId=b.dataset.post;if(postId){showView('feed');openComments(postId)}});await updateNotifBadge()}
$('markAllReadBtn').onclick=async()=>{const {error}=await sb.rpc('mark_all_notifications_read');if(error)return toast(error.message);await loadNotifications()};
document.querySelectorAll('[data-view]').forEach(b=>b.addEventListener('click',()=>showView(b.dataset.view)));
$('newMessageBtn').onclick=showNewMessagePicker;
$('refreshFeed').onclick=async()=>{await Promise.all([loadFeed(),loadProfileStrip()])};
$('startLiveBtn').onclick=startLive;$('endLiveBtn').onclick=endLive;$('closeLive').onclick=()=>closeLive(false);

async function logout(){await sb.auth.signOut()}
$('logoutTop').onclick=logout;$('logoutSide').onclick=logout;

async function boot(session){
  if(!session){state.user=null;state.profile=null;clearInterval(state.notifTimer);authView.classList.remove('hidden');appView.classList.add('hidden');return}
  state.user=session.user;authView.classList.add('hidden');appView.classList.remove('hidden');await loadProfile();await syncLegacyVideoCovers();await Promise.all([loadFeed(),loadProfileStrip(),updateNotifBadge()]);showView('feed');
  clearInterval(state.notifTimer);state.notifTimer=setInterval(()=>{if(state.user)updateNotifBadge()},30000);
}

if(sb){
  sb.auth.onAuthStateChange((_event,session)=>{setTimeout(()=>boot(session),0)});
  sb.auth.getSession().then(({data})=>boot(data.session)).catch(()=>{authView.classList.remove('hidden');appView.classList.add('hidden')});
}else{
  authView.classList.remove('hidden');
  appView.classList.add('hidden');
  console.warn('Supabase library was not available at page load. Authentication UI remains available.');
}

window.addEventListener('click',(e)=>{if(e.target===composer){composer.classList.add('hidden');clearPreview()}if(e.target===$('commentsModal'))$('commentsModal').classList.add('hidden');if(e.target===$('shareMessageModal')){$('shareMessageModal').classList.add('hidden');state.sharePost=null}if(e.target===$('liveModal'))closeLive(false)});
document.addEventListener('pointerdown',()=>{state.musicAutoplayUnlocked=true},{once:true,passive:true});
window.addEventListener('beforeunload',()=>{if(state.liveStream&&state.liveSession){try{navigator.sendBeacon?.(SUPABASE_URL+'/rest/v1/live_sessions?id=eq.'+state.liveSession.id,'')}catch(e){}}});
